		{"403", 403, "", "", "registry returned 403"},
		{"404", 404, "", "", "registry returned 404"},
		{"405", 405, "", "", "registry returned 405"},
		{"429", 429, "", "", "registry returned 429"},
		{"500", 500, "", "", "registry returned 500"},
