				if tt.challenge != "" {
					w.Header().Set("Www-Authenticate", tt.challenge)
				}
				w.WriteHeader(tt.code)
			}))
			defer srv.Close()

			_, err := ListRegistryTags(srv.URL, "library/alpine", "", "")
			var se *StatusError
			if !errors.As(err, &se) {
				t.Fatalf("err = %v (%T), want a *StatusError", err, err)
			}
