21	// bearerRegistry serves a Bearer-protected tag list. tokenHandler answers the
22	// token endpoint; tagsHandler answers an authorized /tags/list request.
23	func bearerRegistry(t *testing.T, tokenHandler, tagsHandler http.HandlerFunc) *httptest.Server {
24		t.Helper()
25		var srv *httptest.Server
26		srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
27			switch {
28			case r.URL.Path == "/token":
29				tokenHandler(w, r)
30			case r.Header.Get("Authorization") == "Bearer tok":
31				tagsHandler(w, r)
32			default:
33				w.Header().Set("Www-Authenticate", fmt.Sprintf(`Bearer realm="%s/token",service="reg"`, srv.URL))
34				w.WriteHeader(http.StatusUnauthorized)
35			}
36		}))
37		t.Cleanup(srv.Close)
38		return srv
39	}
