12	)
13	
14	// registryHTTPClient is swapped by tests that must reach a stand-in for a
15	// registry by another address.
16	var registryHTTPClient = &http.Client{Timeout: 15 * time.Second}
17	
18	const (
19		// maxTagPages bounds how many pages of a tag list are followed. A registry
20		// that pages (`?n=`, `Link: rel="next"`) answers a page at a time, and one
21		// that keeps answering "next" must not hold a caller forever.
22		maxTagPages = 100
23		// maxTagResponse bounds one page. Docker Hub answers a whole list in one
24		// response when no page size is given — measured at 9 125 tags for
25		// library/node (§3.2) — so the bound is generous, but it is a bound.
26		maxTagResponse = 32 << 20
27	)
28	
29	// StatusSource says which endpoint answered with a non-success status.
30	type StatusSource int
31	
32	const (
33		// SourceRegistry is the registry's v2 API.
34		SourceRegistry StatusSource = iota
35		// SourceToken is the Bearer token endpoint.
36		SourceToken
37	)
38	
39	// StatusError is a registry or token endpoint answering with a non-success
40	// status. Failures that are not a status (unreadable body, missing realm, no
41	// token field) are plain errors.
42	type StatusError struct {
43		Code   int
44		Source StatusSource
45		// Challenge is the Www-Authenticate header of a 401 whose challenge is not
46		// Bearer; empty otherwise.
47		Challenge string
48		// unexpectedChallenge tells that 401 apart from a 401 answered after a
49		// token exchange, so Error() keeps both historical messages.
50		unexpectedChallenge bool
51	}
52	
53	// Error returns the message the plain errors carried before the type existed.
54	func (e *StatusError) Error() string {
55		switch {
56		case e.Source == SourceToken:
57			return fmt.Sprintf("token endpoint returned %d", e.Code)
58		case e.unexpectedChallenge:
59			return fmt.Sprintf("unexpected auth challenge: %s", e.Challenge)
60		}
61		return fmt.Sprintf("registry returned %d", e.Code)
62	}
63	
64	// ListRegistryTags lists the tags of a repository through the registry's v2 API.
65	//
66	// apiURL is the API base (see the browser's registryAPIURL). Credentials, when
67	// given, go as Basic auth and, on a 401 that names a Bearer realm, to that
68	// realm's token endpoint — the flow Docker Hub and most hosted registries use.
