10		"strings"
11		"time"
12	)
13	
14	// registryHTTPClient is swapped by tests that must reach a stand-in for a
15	// registry by another address.
16	var registryHTTPClient = &http.Client{Timeout: 15 * time.Second}
17	
18	const (
19		// maxTagPages bounds how many pages of a tag list are followed. A registry
20		// that pages (`?n=`, `Link: rel="next"`) answers a page at a time, and one
21		// that keeps answering "next" must not hold a caller forever.
22		maxTagPages = 100
23		// maxTagResponse bounds one page. Docker Hub answers a whole list in one
24		// response when no page size is given — measured at 9 125 tags for
25		// library/node (§3.2) — so the bound is generous, but it is a bound.
26		maxTagResponse = 32 << 20
27	)
28	
29	// StatusSource says which endpoint answered with a non-success status.
30	type StatusSource int
31	
32	const (
33		// SourceRegistry is the registry's v2 API.
34		SourceRegistry StatusSource = iota
35		// SourceToken is the Bearer token endpoint.
36		SourceToken
37	)
38	
39	// StatusError is a registry or token endpoint answering with a non-success
40	// status. Failures that are not a status (unreadable body, missing realm, no
41	// token field) are plain errors.
42	type StatusError struct {
43		Code   int
44		Source StatusSource
45		// Challenge is the Www-Authenticate header of a 401 whose challenge is not
46		// Bearer; empty otherwise.
47		Challenge string
48		// unexpectedChallenge tells that 401 apart from a 401 answered after a
49		// token exchange, so Error() keeps both historical messages.
50		unexpectedChallenge bool
51	}
52	
53	// Error returns the message the plain errors carried before the type existed.
54	func (e *StatusError) Error() string {
55		switch {
56		case e.Source == SourceToken:
57			return fmt.Sprintf("token endpoint returned %d", e.Code)
58		case e.unexpectedChallenge:
59			return fmt.Sprintf("unexpected auth challenge: %s", e.Challenge)
60		}
61		return fmt.Sprintf("registry returned %d", e.Code)
62	}
63	
64	// ListRegistryTags lists the tags of a repository through the registry's v2 API.
65	//
66	// apiURL is the API base (see the browser's registryAPIURL). Credentials, when
67	// given, go as Basic auth and, on a 401 that names a Bearer realm, to that
68	// realm's token endpoint — the flow Docker Hub and most hosted registries use.
69	// The token is kept for the following pages.
70	//
71	// The list is followed across pages: whatever a registry caps a response at,
72	// and Docker Hub does not, a repository with more tags than one page holds is
73	// returned whole. This is the one tag lister that speaks the Bearer flow; the
74	// template client's ListTags (Client.ListTags) reads a registry the user
75	// configured for templates and only ever sends Basic auth.
76	func ListRegistryTags(apiURL, repo, username, password string) ([]string, error) {
77		return ListRegistryTagsContext(context.Background(), apiURL, repo, username, password)
78	}
79	
80	// ListRegistryTagsContext is ListRegistryTags bound to ctx: a cancelled or
81	// expired context stops the walk, including a request in flight, and the
82	// returned error wraps the context's error. A context already done sends
83	// nothing. registryHTTPClient's own timeout still applies per request; when
84	// both expire, whichever comes first ends the request, and either way the
85	// error satisfies errors.Is(err, context.DeadlineExceeded).
86	func ListRegistryTagsContext(ctx context.Context, apiURL, repo, username, password string) ([]string, error) {
87		next := fmt.Sprintf("%s/v2/%s/tags/list", strings.TrimSuffix(apiURL, "/"), repo)
88		var (
89			tags  []string
90			token string
91		)
92		for page := 0; next != ""; page++ {
93			if page == maxTagPages {
94				return nil, fmt.Errorf("tag list of %s is longer than %d pages", repo, maxTagPages)
95			}
96			body, link, usedToken, err := registryGETContext(ctx, next, username, password, token)
97			if err != nil {
98				return nil, err
99			}
100			token = usedToken
101			var result struct {
102				Tags []string `json:"tags"`
103			}
104			if err := json.Unmarshal(body, &result); err != nil {
105				return nil, fmt.Errorf("decode tags response: %w", err)
106			}
107			tags = append(tags, result.Tags...)
108			next = resolveNext(next, link)
109		}
110		return tags, nil
111	}
112	
113	// registryGET performs a GET, answering a Bearer challenge once. It returns the
114	// body, the Link header, and the token to send on the following requests.
115	func registryGET(rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
116		return registryGETContext(context.Background(), rawURL, username, password, token)
117	}
118	
119	// registryGETContext is registryGET bound to ctx.
120	func registryGETContext(ctx context.Context, rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
121		resp, token, err := registryDoContext(ctx, http.MethodGet, rawURL, "", username, password, token)
122		if err != nil {
123			return nil, "", token, err
124		}
125		defer func() { _ = resp.Body.Close() }()
126		if resp.StatusCode != http.StatusOK {
127			return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
128		}
129		body, err = io.ReadAll(io.LimitReader(resp.Body, maxTagResponse))
130		return body, resp.Header.Get("Link"), token, err
131	}
132	
133	// registryDo sends one request, answering a Bearer challenge once. The caller
134	// closes the response body and reads the status.
135	func registryDo(method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
136		return registryDoContext(context.Background(), method, rawURL, accept, username, password, token)
137	}
138	
139	// registryDoContext is registryDo bound to ctx.
140	func registryDoContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
141		resp, err := doRequestContext(ctx, method, rawURL, accept, username, password, token)
142		if err != nil {
143			return nil, token, err
144		}
145		if resp.StatusCode != http.StatusUnauthorized {
146			return resp, token, nil
147		}
148		challenge := resp.Header.Get("Www-Authenticate")
149		_ = resp.Body.Close()
150		if !strings.HasPrefix(challenge, "Bearer ") {
151			return nil, token, &StatusError{Code: http.StatusUnauthorized, Source: SourceRegistry, Challenge: challenge, unexpectedChallenge: true}
152		}
153		token, err = exchangeBearerTokenContext(ctx, challenge[7:], username, password)
154		if err != nil {
155			return nil, "", err
156		}
157		if resp, err = doRequestContext(ctx, method, rawURL, accept, "", "", token); err != nil {
158			return nil, token, fmt.Errorf("%s (retry) %s: %w", method, rawURL, err)
159		}
160		return resp, token, nil
161	}
162	
163	// doRequest sends one request: a bearer token when there is one, Basic auth
164	// when there are credentials and no token.
165	func doRequest(method, rawURL, accept, username, password, token string) (*http.Response, error) {
166		return doRequestContext(context.Background(), method, rawURL, accept, username, password, token)
167	}
168	
169	// doRequestContext is doRequest bound to ctx; a context already done sends
170	// nothing.
171	func doRequestContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, error) {
172		req, err := http.NewRequestWithContext(ctx, method, rawURL, nil)
173		if err != nil {
174			return nil, fmt.Errorf("build request: %w", err)
175		}
176		if accept != "" {
177			req.Header.Set("Accept", accept)
178		}
179		switch {
180		case token != "":
181			req.Header.Set("Authorization", "Bearer "+token)
182		case username != "" && password != "":
183			req.SetBasicAuth(username, password)
184		}
185		resp, err := registryHTTPClient.Do(req)
186		if err != nil {
187			return nil, fmt.Errorf("%s %s: %w", method, rawURL, err)
188		}
189		return resp, nil
190	}
191	
192	// manifestAccept lists every manifest kind a tag can point to. A multi-platform
193	// tag is an index (or a Docker manifest list), and its digest is the one `docker
194	// pull` records in RepoDigests; asking for a single-platform manifest only
195	// would make the registry convert or refuse, and the digests would not match.
196	var manifestAccept = strings.Join([]string{
197		"application/vnd.oci.image.index.v1+json",
198		"application/vnd.docker.distribution.manifest.list.v2+json",
199		"application/vnd.oci.image.manifest.v1+json",
200		"application/vnd.docker.distribution.manifest.v2+json",
201	}, ", ")
202	
203	// ManifestDigest returns the digest a tag currently points to, from the
204	// registry's Docker-Content-Digest header.
205	//
206	// It is a HEAD request: Docker Hub does not count a HEAD against the pull rate
207	// limit, and nothing but the header is needed.
208	func ManifestDigest(apiURL, repo, tag, username, password string) (string, error) {
209		rawURL := fmt.Sprintf("%s/v2/%s/manifests/%s", strings.TrimSuffix(apiURL, "/"), repo, url.PathEscape(tag))
210		resp, _, err := registryDo(http.MethodHead, rawURL, manifestAccept, username, password, "")
211		if err != nil {
212			return "", err
213		}
214		_ = resp.Body.Close()
215		if resp.StatusCode != http.StatusOK {
216			return "", fmt.Errorf("registry returned %d for %s:%s", resp.StatusCode, repo, tag)
217		}
218		digest := resp.Header.Get("Docker-Content-Digest")
219		if digest == "" {
220			return "", fmt.Errorf("registry gave no digest for %s:%s", repo, tag)
221		}
222		return digest, nil
223	}
224	
225	// RegistryAPIBase is the v2 API root of a registry named in an image reference:
226	// Docker Hub has its own host, a local registry is reached over plain HTTP, and
227	// everything else over HTTPS. An empty registry is Docker Hub.
228	func RegistryAPIBase(registry string) string {
229		switch {
230		case registry == "":
231			return "https://registry-1.docker.io"
232		case strings.HasPrefix(registry, "localhost") || strings.HasPrefix(registry, "127.0.0.1"):
233			return "http://" + registry
234		}
235		return "https://" + registry
236	}
237	
238	// resolveNext is the URL a Link header's rel="next" points to, resolved against
239	// the page it came with — registries send it as a path — or "" when there is
240	// none. A next link that leads back to the page just read ends the walk rather
241	// than looping on it.
242	func resolveNext(current, link string) string {
243		for _, part := range strings.Split(link, ",") {
244			target, rel, ok := strings.Cut(strings.TrimSpace(part), ";")
245			if !ok || !strings.Contains(rel, `rel="next"`) {
246				continue
247			}
248			target = strings.Trim(strings.TrimSpace(target), "<>")
249			base, err := url.Parse(current)
250			if err != nil {
251				return ""
252			}
253			ref, err := url.Parse(target)
254			if err != nil {
255				return ""
256			}
257			if next := base.ResolveReference(ref).String(); next != current {
258				return next
259			}
260		}
261		return ""
262	}
