264	// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
265	func exchangeBearerToken(challenge, username, password string) (string, error) {
266		return exchangeBearerTokenContext(context.Background(), challenge, username, password)
267	}
268	
269	// exchangeBearerTokenContext is exchangeBearerToken bound to ctx.
270	func exchangeBearerTokenContext(ctx context.Context, challenge, username, password string) (string, error) {
271		params := parseBearerChallenge(challenge)
272		realm, ok := params["realm"]
273		if !ok {
274			return "", fmt.Errorf("bearer challenge missing realm")
275		}
276		u, err := url.Parse(realm)
277		if err != nil {
278			return "", fmt.Errorf("parse realm %q: %w", realm, err)
279		}
280		q := u.Query()
281		if s, ok := params["service"]; ok {
282			q.Set("service", s)
283		}
284		if s, ok := params["scope"]; ok {
285			q.Set("scope", s)
286		}
287		u.RawQuery = q.Encode()
288	
289		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
290		if err != nil {
291			return "", fmt.Errorf("build token request: %w", err)
292		}
293		if username != "" && password != "" {
294			req.SetBasicAuth(username, password)
295		}
296		resp, err := registryHTTPClient.Do(req)
297		if err != nil {
298			return "", fmt.Errorf("fetch token: %w", err)
299		}
300		defer func() { _ = resp.Body.Close() }()
301		if resp.StatusCode != http.StatusOK {
302			return "", &StatusError{Code: resp.StatusCode, Source: SourceToken}
303		}
304		body, err := io.ReadAll(resp.Body)
305		if err != nil {
306			return "", fmt.Errorf("read token response: %w", err)
307		}
308		var result struct {
309			Token       string `json:"token"`
310			AccessToken string `json:"access_token"`
311		}
312		if err := json.Unmarshal(body, &result); err != nil {
313			return "", fmt.Errorf("decode token response: %w", err)
314		}
315		if result.Token != "" {
316			return result.Token, nil
317		}
318		if result.AccessToken != "" {
319			return result.AccessToken, nil
320		}
321		return "", fmt.Errorf("token response contained no token field")
322	}
323	
324	// parseBearerChallenge parses the value portion of a Www-Authenticate: Bearer header.
325	// Example: `realm="https://auth.docker.io/token",service="registry.docker.io"`
326	func parseBearerChallenge(s string) map[string]string {
327		params := make(map[string]string)
328		for _, part := range strings.Split(s, ",") {
329			part = strings.TrimSpace(part)
330			idx := strings.IndexByte(part, '=')
331			if idx < 0 {
332				continue
333			}
334			key := strings.TrimSpace(part[:idx])
335			val := strings.Trim(strings.TrimSpace(part[idx+1:]), `"`)
336			params[key] = val
337		}
338		return params
339	}
